<script>
let text = $state('');
$derived.by(() => {
  const words = text.split(/\s+/).length;
  const chars = text.length;
  return {
    wordCount: words,
    charCount: chars,
    isLong: words > 15
  };
});
</script>

<div>
  <input data-testid="text-input" bind:value={text} />
  <button data-testid="clear-button" onclick={() => text = ''}>Clear</button>
  <div data-testid="word-count">{derived.wordCount}</div>
  <div data-testid="char-count">{derived.charCount}</div>
  <div data-testid="length-indicator">{derived.isLong ? 'Long text' : 'Short text'}</div>
</div>
